   "orig": "Calibro 35 - Ellroy vs L.A.",
   "lead": "Il gruppo musicale Calibro 35 ha realizzato la colonna sonora del documentario vincitore del Nastro d'Argento diretto da Francesco Zippel e dedicato al celebre scrittore noir americano James Ellroy. Lo riferisce OndaRock.",
