   "id": "z04e987ca",
   "sez": "economia",
   "titolo": "Giappone: scetticismo delle imprese sul taglio dell'imposta sui consumi",
   "orig": "Japanese Companies Skeptical Over Proposed Consumption Tax Cut",
   "lead": "Un recente sondaggio condotto in Giappone rivela un forte scetticismo tra le aziende nazionali riguardo alla proposta governativa di tagliare l'imposta sui consumi. Secondo la ricerca, solo il 18% delle società interpellate ritiene che tale misura possa effettivamente stimolare l'economia del Paese. Al contrario, oltre la metà delle imprese coinvolte non prevede alcun beneficio significativo derivante dalla riduzione fiscale. Il dato sottolinea la sfiducia degli operatori economici verso l'efficacia degli attuali strumenti di politica fiscale nipponica. Lo riferisce Nippon.com.",
   "more": [
    "L'imposta sui consumi in Giappone è l'equivalente dell'IVA europea. Da anni il governo discute se alzare o abbassare questa aliquota per bilanciare la necessità di entrate fiscali con l'esigenza di rilanciare i consumi interni, in un contesto economico caratterizzato da una lunga stagnazione e da un invecchiamento demografico."
   ],
