   "sez": "cultura",
   "titolo": "In arrivo la serie TV \"Carrie\" di Mike Flanagan",
   "orig": "Carrie, una nuova serie tv per raccontare la crudeltà del presente",
   "lead": "Mike Flanagan è al lavoro su una nuova serie televisiva che rilegge il celebre romanzo \"Carrie\" di Stephen King. Il progetto si propone di trasporre la storia in una chiave contemporanea, focalizzandosi sugli orrori del bullismo moderno e sulle crudeltà del presente. La serie mira a esplorare le dinamiche psicologiche e sociali tipiche della nostra epoca, offrendo una visione aggiornata del classico dell'orrore che ha già conosciuto diverse interpretazioni cinematografiche. Lo riferisce Fumettologica.",
   "more": [
    "Mike Flanagan è un regista e sceneggiatore noto per i suoi fortunati adattamenti di opere horror, in particolare quelle di Stephen King. La sua cifra stilistica si caratterizza per una grande attenzione alla profondità dei personaggi e alla dimensione emotiva dell'orrore, rendendolo uno degli autori più apprezzati del genere televisivo attuale."
   ],
