   "sez": "tech",
   "titolo": "Premio Emmy per la tecnologia AI di Brahma AI",
   "orig": "Vlaming wint Emmy voor AI-technologie: \"Tom Hanks weer 20 jaar oud maken of Frans laten spreken\"",
   "lead": "Jo Plaete e la sua azienda Brahma AI hanno vinto un Technology & Engineering Emmy Award grazie a una innovativa tecnologia basata sull'intelligenza artificiale per gli effetti visivi. Questo sistema permette di ringiovanire digitalmente gli attori, come avvenuto per rendere Tom Hanks nuovamente ventenne, o di farli parlare in altre lingue mantenendo inalterate le espressioni facciali e il timbro della voce. Secondo Plaete, questa innovazione potrebbe consentire anche ai film in lingua locale di conquistare più facilmente il mercato internazionale, abbattendo le barriere linguistiche. Lo riferisce VRT NWS.",
   "more": [
    "L'intelligenza artificiale applicata al cinema sta rivoluzionando la post-produzione. Tecniche come il \"de-aging\" e la manipolazione del parlato permettono una flessibilità creativa senza precedenti, riducendo i costi di trucco e doppiaggio tradizionale, sebbene sollevino importanti questioni etiche e legali sulla protezione dell'immagine degli attori."
   ],
