   "id": "z3fe14c8e",
   "sez": "salute",
   "titolo": "Eggzempic: i rischi della nuova dieta a base di uova",
   "orig": "Eggzempic: la folle dieta da 6 uova al giorno commentata dal medico",
   "lead": "Sui social network si sta diffondendo la \"Eggzempic\", una controversa dieta che prevede il consumo di sei uova al giorno per perdere peso rapidamente. Gli esperti medici, tra cui il presidente della Società Italiana di Nutrizione Clinica e Metabolismo, hanno lanciato un allarme sulla pericolosità di questo regime alimentare estremo. La dieta viene definita rischiosa per la salute a causa del forte squilibrio nutrizionale e dei potenziali danni metabolici che può provocare, avvertendo gli utenti di non seguire tendenze alimentari prive di basi scientifiche. Lo riferisce La Cucina Italiana.",
   "more": [
    "Le diete mono-alimento o estremamente sbilanciate possono causare carenze vitaminiche, problemi renali e alterazioni del colesterolo. Il termine \"Eggzempic\" richiama ironicamente un noto farmaco per il diabete usato spesso impropriamente per dimagrire, sottolineando la ricerca ossessiva di soluzioni rapide ma potenzialmente nocive per la perdita di peso."
   ],
