   "orig": "FILDAK : l’État veut renforcer le rôle des professionnels du livre",
   "lead": "La diciottesima edizione della Fiera internazionale del libro e del materiale didattico (FILDAK) prende il via giovedì 15 octobre al Centre international du commerce extérieur du Sénégal (CICES) a Dakar, in Senegal, dopo una lunga interruzione durata otto anni. Questo appuntamento di rilancio punta a rafforzare il ruolo e il coinvolgimento diretto dei professionisti del settore nella pianificazione e nello sviluppo della fiera libraria. Lo riferisce Le Soleil.",
