   "lead": "Gli ingegneri dovrebbero adottare una politica di acquisto orientata alla massima qualità e durata per la manutenzione delle strade nel Regno Unito, dove si registra un arretrato record di riparazioni alle carreggiate pari a 18,62 miliardi di sterline. Il dato emerge dall'indagine ALARM 2026 dell'Asphalt Industry Alliance, che evidenzia l'enorme portata della sfida infrastrutturale attuale. Lo riferisce New Civil Engineer.",
