   "lead": "L'ex amministratore delegato di Recognition Music, Ben Katovsky, ha lasciato il proprio incarico presso il fondo di cataloghi musicali per assumere il ruolo di vertice a Pipeline. Nella nuova posizione, Katovsky affiancherà la propria esperienza nella gestione dei cataloghi alle competenze negoziali di Matt Spetzler per favorire la crescita della piattaforma di anticipi per gli artisti. Lo riferisce Billboard.",
