   "lead": "I 27 leader dell'Unione europea si riuniscono per due giorni a Bruxelles con tre nodi aperti: il caro energia, il bilancio pluriennale 2028-2034 e l'uso dei circa 210 miliardi di euro di asset russi congelati, in gran parte depositati in Belgio. Il Belgio continua a opporsi per i rischi legali e finanziari, mentre la Banca centrale europea avverte che toccare le riserve russe potrebbe minare la fiducia nell'euro: nessuna decisione definitiva è attesa su questo fronte. Sul tavolo anche la linea più dura verso la Cina e la proposta Usa, respinta dall'Europa, per lo sblocco di altri asset.",
