     "c": "Bishkek",
     "p": "XX",
     "t": "Il testo non era leggibile: si dispone solo del titolo, che annuncia la firma presidenziale di una legge che introduce l'ergastolo e l'abolizione della prescrizione per abusi sessuali su minori; il giudizio è quindi parziale.",
