   "sez": "ingegneria",
   "titolo": "Il ponte di Dandong-Sinuiju: dieci anni di attesa per un'infrastruttura già pronta",
   "testo": "Il nuovo ponte a quattro corsie tra la cinese Dandong e la nordcoreana Sinuiju era stato completato già nel 2014, ma è rimasto chiuso per un decennio in attesa che Pyongyang costruisse le strade di collegamento e le strutture doganali necessarie sul proprio lato di confine.",
